/// <summary>
/// Contract class for batch job
/// </summary>
[DataContractAttribute]
class NDXRicoReqDocuTransferResultsContract implements SysOperationInitializable
{
    boolean allMissingTransferedRicoDocuments;
    NDXRicoReqDocProt ndxRicoReqDocProt;

    NDXRicoReqDocuTransferResultsController controller;
    Dialog dialog;

}

Method.Source:
[DataMemberAttribute("NDXRicoReqDocProt")]
public NDXRicoReqDocProt parmNdxRicoReqDocProt(NDXRicoReqDocProt _ndxRicoReqDocProt = ndxRicoReqDocProt)
{
    ndxRicoReqDocProt = _ndxRicoReqDocProt;
    return ndxRicoReqDocProt;
}

[DataMemberAttribute("allMissing"), SysOperationLabelAttribute("@NDX:NDXAllRicoNotProcessed"), SysOperationHelpText("@NDX:NDXAllRicoNotProcessed_Help"),  SysOperationDisplayOrder('1')]
public NoYes parmAllMissingTransferedRicoDocuments(NoYes _allMissingTransferedRicoDocuments = allMissingTransferedRicoDocuments)
{
    allMissingTransferedRicoDocuments = _allMissingTransferedRicoDocuments;
    return allMissingTransferedRicoDocuments;
}

/// <summary>
/// Information on a dialog
/// </summary>
/// <param name = "_controller">job controller</param>
public void buildDialogParameters(NDXRicoReqDocuTransferResultsController _controller)
{
    str requestInfo;
    controller = _controller;
    dialog = _controller.dialog();
    DialogText dlgDocumentTransferReq;

    requestInfo = strFmt('%1\n%2\n%3\n%4\n%5\n%6',ndxRicoReqDocProt.RicoLogID, ndxRicoReqDocProt.Action, ndxRicoReqDocProt.NDXRicoKalkBVNr, ndxRicoReqDocProt.KCSKBVRequestID, ndxRicoReqDocProt.Filename, ndxRicoReqDocProt.CreatedDateTime);

    dlgDocumentTransferReq = dialog.addText(requestInfo);
}
